	case "register":
		if len(args) != 3 {
			fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions register <archive-dir> <spec-file>")
			os.Exit(2)
		}
		var raw []byte
		var err error
		if args[2] == "-" {
			raw, err = io.ReadAll(os.Stdin)
		} else {
			raw, err = os.ReadFile(args[2])
		}
		if err != nil {
