	res := runCLI(t, "replay", "--version", "candC", inputPath, dir)
	if res.exitCode != 1 {
		t.Fatalf("exit = %d, want 1; stdout=%q stderr=%q", res.exitCode, res.stdout, res.stderr)
	}
