		t.Fatal(err)
	}
	if !reflect.DeepEqual(before, after) {
		t.Fatalf("refused replays changed the archive")
	}
	if _, err := mevwatch.Query(dir, "1", "0xnew"); err == nil {
		t.Fatalf("new block archived by a refused replay")
	}
}

