103			t.Fatalf("first run: got %d, want 1", len(first))
104		}
105		// Repeated generation, wider range, overlapping range, and a "restart"
106		// (fresh call against the same on-disk archive) create nothing new while
107		// the threshold stays at 3 (the severity-2 displacement is simply
108		// ineligible, not processed).
109		for _, bounds := range [][2]uint64{{10, 10}, {0, 100}, {5, 15}, {10, 10}} {
