1304	func TestRevokeSuppressionConcurrentConsistent(t *testing.T) {
1305		dir := t.TempDir()
1306		mustReplay(t, dir, twoFindingsInput)
1307		spec := `{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":0,"endHeight":200,"reason":"r"}`
1308		if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
1309			t.Fatal(err)
1310		}
1311	
1312		const n = 12
1313		var wg sync.WaitGroup
1314		genErrs := make([]error, n)
1315		statuses := make([]string, n)
1316		start := make(chan struct{})
1317		// Half the goroutines generate, half revoke, all retrying through busy
1318		// errors the way a real caller does. Each generation must observe one
1319		// consistent condition set (suppressed pre-revoke or alert post-revoke),
1320		// never a half state.
1321		retryBusy := func(op func() error) error {
1322			for attempt := 0; attempt < 1000; attempt++ {
1323				err := op()
1324				if errors.Is(err, ErrBusy) {
1325					time.Sleep(time.Millisecond)
1326					continue
1327				}
1328				return err
1329			}
1330			return ErrBusy
1331		}
1332		for i := 0; i < n; i++ {
1333			wg.Add(1)
1334			go func(i int) {
1335				defer wg.Done()
1336				<-start
1337				if i%2 == 0 {
1338					genErrs[i] = retryBusy(func() error {
1339						recs, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1340						if err == nil {
1341							for _, r := range recs {
1342								if r.Finding.TxHash == "0xv" {
1343									statuses[i] = r.Status
1344								}
1345							}
1346						}
1347						return err
1348					})
1349				} else {
1350					genErrs[i] = retryBusy(func() error {
1351						_, _, err := RevokeSuppression(dir, "s1")
1352						return err
1353					})
1354				}
1355			}(i)
1356		}
1357		close(start)
1358		wg.Wait()
1359	
1360		for i, err := range genErrs {
1361			if err != nil {
1362				t.Fatalf("goroutine %d unexpected error: %v", i, err)
1363			}
1364		}
1365		// Exactly one generation creates the sandwich record; its status must be
1366		// one coherent outcome, and only the matching condition ids are stored.
1367		hist, err := AlertHistory(dir, "1", "ops", 0, 100)
1368		if err != nil {
1369			t.Fatal(err)
1370		}
1371		final := ""
1372		count := 0
1373		for _, r := range hist {
1374			if r.Finding.TxHash == "0xv" {
1375				count++
1376				final = r.Status
1377				if len(r.Suppressions) > 1 {
1378					t.Fatalf("inconsistent hit set: %+v", r.Suppressions)
1379				}
1380			}
1381		}
1382		if count != 1 {
1383			t.Fatalf("sandwich processed %d times, want exactly 1", count)
1384		}
1385		if final != AlertStatusAlert && final != AlertStatusSuppressed {
1386			t.Fatalf("final status %q is neither coherent pre/post-revocation state", final)
1387		}
1388		// The generator that created the record reports the same status it
1389		// committed; no generator may return an incoherent status.
1390		nonEmpty := 0
1391		for i, s := range statuses {
1392			if s == "" {
1393				continue
1394			}
1395			nonEmpty++
1396			if s != final {
1397				t.Fatalf("generator %d observed status %q but history holds %q", i, s, final)
1398			}
1399		}
1400		if nonEmpty != 1 {
1401			t.Fatalf("exactly one generation must create the record, %d reported it", nonEmpty)
1402		}
1403	}
